--- implementation/warlock-preview-provider-v94/native/preview-control-delivery.h
+++ implementation/warlock-preview-provider-v95/native/preview-control-delivery.h
@@ -0,0 +1,52 @@
+#pragma once
+#include "preview-control.h"
+#include <string.h>
+
+/* The caller derives receiver from the actual native WebKit target. Binding
+ * and epoch are decoded canonically from the packet. This is delivery metadata;
+ * every effect still requires its original native handler validation. */
+typedef struct {
+    guint64 lifetime,session,frontend,receiver,epoch;
+} PreviewControlGrant;
+typedef enum {
+    PREVIEW_CONTROL_REFUSED,
+    PREVIEW_CONTROL_INVOKE,
+    PREVIEW_CONTROL_REPEAT_RECEIPT
+} PreviewControlDecision;
+typedef struct {
+    PreviewControl prefix;
+    PreviewControlGrant grant;
+    gboolean initialized;
+    char pending[4097],latest[4097];
+} PreviewControlDelivery;
+static inline gboolean preview_control_grant_equal(PreviewControlGrant a,PreviewControlGrant b) {
+    return a.lifetime==b.lifetime && a.session==b.session && a.frontend==b.frontend &&
+        a.receiver==b.receiver && a.epoch==b.epoch;
+}
+static inline gboolean preview_control_delivery_init(PreviewControlDelivery *state,PreviewControlGrant grant) {
+    if(!state || state->initialized || state->prefix.delivered || state->prefix.inFlight || state->prefix.ordered ||
+       !grant.lifetime || !grant.session || !grant.frontend || !grant.receiver || !grant.epoch)return FALSE;
+    state->grant=grant;state->initialized=TRUE;return TRUE;
+}
+static inline PreviewControlDecision preview_control_delivery_receive(PreviewControlDelivery *state,
+        PreviewControlGrant actual,guint64 ordinal,const char *wire,gsize length) {
+    if(!state || !state->initialized || !preview_control_grant_equal(state->grant,actual) ||
+       !ordinal || !wire || !length || length>4096 || strlen(wire)!=length || state->prefix.inFlight)
+        return PREVIEW_CONTROL_REFUSED;
+    if(ordinal==state->prefix.delivered && !strcmp(wire,state->latest))
+        return PREVIEW_CONTROL_REPEAT_RECEIPT;
+    if(!preview_control_next(&state->prefix,ordinal))return PREVIEW_CONTROL_REFUSED;
+    // Fixed storage is reserved before invoking a handler. No receipt can make
+    // this packet enter the handler again, even if its effect outcome is Unknown.
+    memcpy(state->pending,wire,length+1);
+    preview_control_begin(&state->prefix,ordinal);return PREVIEW_CONTROL_INVOKE;
+}
+static inline gboolean preview_control_delivery_complete(PreviewControlDelivery *state,guint64 ordinal) {
+    if(!state || !state->initialized || !state->prefix.inFlight ||
+       state->prefix.delivered==G_MAXUINT64 || ordinal!=state->prefix.delivered+1)return FALSE;
+    memcpy(state->latest,state->pending,sizeof(state->latest));
+    preview_control_delivered(&state->prefix,ordinal);state->pending[0]='\0';return TRUE;
+}
+static inline guint64 preview_control_delivery_receipt(const PreviewControlDelivery *state) {
+    return state && state->initialized && !state->prefix.inFlight?state->prefix.delivered:0;
+}

--- implementation/warlock-preview-provider-v94/native/control-outbox-fixture.cpp
+++ implementation/warlock-preview-provider-v95/native/control-outbox-fixture.cpp
@@ -0,0 +1,39 @@
+#include "preview_wire.hpp"
+#include "preview-control-delivery.h"
+#include <iostream>
+using namespace preview;
+using namespace preview::bridge;
+int main(){try {
+    const PreviewControlGrant owner{17,18,19,77,1};PreviewControlDelivery state{};
+    require(preview_control_delivery_init(&state,owner),"Original fixture receiver grant");
+    uint64_t invoked=0;std::string line;
+    while(std::getline(std::cin,line)) {
+        require(line.size()<=65536,"Bounded native fixture input");Json envelope(line);
+        const std::string_view op=Json::text(envelope.object(),"op");
+        if(op=="finish") {require(!state.prefix.inFlight,"Normal fixture close outside dispatch");std::cout<<"{\"finished\":true,\"invoked\":"<<invoked<<"}"<<std::endl;return 0;}
+        require(op=="packet","Closed fixture operation");const std::string wire=Json::text(envelope.object(),"wire");
+        Json message(wire);auto packet=message.object();
+        Json::fields(packet,{"previewProtocol","kind","binding","receiverEpoch","controlOrdinal","entries"});
+        require(Json::integer(packet,"previewProtocol")==3 && std::string_view(Json::text(packet,"kind"))=="preview-commands","Typed control protocol");
+        const auto binding=decodeBinding(Json::child(packet,"binding"));
+        const PreviewControlGrant incoming{binding.lifetime.value,binding.session.value,binding.frontend.value,77,message.counter("receiverEpoch")};
+        auto entries=json_object_get_array_member(packet,"entries");require(entries && json_array_get_length(entries)==1,"Singleton control entry");
+        auto entry=json_node_get_object(json_array_get_element(entries,0));Json::fields(entry,{"identity","commands"});
+        require(std::string_view(Json::text(entry,"identity")).starts_with("family:"),"Typed fixture identity");
+        auto commands=json_object_get_array_member(entry,"commands");require(commands && json_array_get_length(commands)==1,"One immutable command");
+        const auto ordinal=message.counter("controlOrdinal");
+        auto decision=preview_control_delivery_receive(&state,incoming,ordinal,wire.c_str(),wire.size());
+        if(decision==PREVIEW_CONTROL_INVOKE) {
+            ++invoked;
+            // A dispatcher can return with an Unknown/refused effect. Its
+            // delivery receipt still cannot authorize a second invocation.
+            require(preview_control_delivery_complete(&state,ordinal),"Complete original dispatch");
+        }
+        const auto receipt=preview_control_delivery_receipt(&state);
+        std::string acknowledgment="null";
+        if(decision!=PREVIEW_CONTROL_REFUSED && receipt)acknowledgment=Wire().integer("previewProtocol",3).text("kind","preview-control-delivered")
+            .begin("binding").binding({{17},{18},{19}}).end().counter("receiverEpoch",1).counter("controlOrdinal",receipt).finish();
+        std::cout<<"{\"decision\":"<<decision<<",\"invoked\":"<<invoked<<",\"effectOutcome\":\"Unknown\",\"receipt\":"<<acknowledgment<<"}"<<std::endl;
+    }
+    require(false,"Explicit normal fixture close");
+}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}

--- implementation/warlock-preview-provider-v94/assets/retained-preview-controls.js
+++ implementation/warlock-preview-provider-v95/assets/retained-preview-controls.js
@@ -0,0 +1,50 @@
+'use strict';
+// Transport only. This file is deliberately not loaded by popup.html until
+// native admission reserves cleanup capacity and receiver recovery is wired.
+// A failed offer is backpressure before admission, never permission to discard
+// an already emitted Elm command. Delivery receipts do not settle effects.
+globalThis.WarlockRetainedPreviewControls = function(grant, post) {
+  const maximum=18446744073709551615n;
+  const fields=(value,names)=>value && typeof value==='object' && !Array.isArray(value) &&
+    Object.keys(value).length===names.length && names.every(name=>Object.hasOwn(value,name));
+  const counter=value=>typeof value==='string' && /^[1-9][0-9]*$/.test(value) && value.length<=20 && BigInt(value)<=maximum;
+  const validBinding=value=>fields(value,['lifetime','session','frontend']) &&
+    ['lifetime','session','frontend'].every(name=>counter(value[name]));
+  if(!fields(grant,['binding','receiverEpoch','capacity']) || !validBinding(grant.binding) ||
+     !counter(grant.receiverEpoch) || !Number.isSafeInteger(grant.capacity) || grant.capacity<=0 || typeof post!=='function')
+    throw new TypeError('Original native grant and bounded reserved capacity required');
+  const binding=Object.freeze({...grant.binding}),epoch=grant.receiverEpoch,capacity=grant.capacity;
+  let issued=0n,confirmed=0n,sending=false;const queue=[];
+  function transmit() {
+    if(sending || !queue.length)return false;
+    sending=true;
+    try {post(queue[0].wire);return true;} catch(_error) {return false;}
+    finally {sending=false;}
+  }
+  function offer(identity,command) {
+    if(queue.length>=capacity || issued===maximum || typeof identity!=='string' || !identity ||
+       !command || typeof command!=='object' || Array.isArray(command))return false;
+    const ordinal=issued+1n;let wire;
+    try {wire=JSON.stringify({previewProtocol:3,kind:'preview-commands',binding,
+      receiverEpoch:epoch,controlOrdinal:String(ordinal),entries:[{identity,commands:[command]}]});}
+    catch(_error) {return false;}
+    if(new TextEncoder().encode(wire).length>4096)return false;
+    // Serialize before consuming an ordinal; caller mutation can never alter a
+    // retained transmission. One outstanding packet enters native at a time.
+    const idle=!queue.length;queue.push(Object.freeze({ordinal,wire}));issued=ordinal;
+    if(idle)transmit();return true;
+  }
+  function acknowledge(receipt) {
+    if(!fields(receipt,['previewProtocol','kind','binding','receiverEpoch','controlOrdinal']) ||
+       receipt.previewProtocol!==3 || receipt.kind!=='preview-control-delivered' ||
+       !validBinding(receipt.binding) || ['lifetime','session','frontend'].some(name=>receipt.binding[name]!==binding[name]) ||
+       receipt.receiverEpoch!==epoch || !counter(receipt.controlOrdinal) || !queue.length ||
+       BigInt(receipt.controlOrdinal)!==queue[0].ordinal)return false;
+    confirmed=queue[0].ordinal;queue.shift();
+    // An unusually synchronous receipt cannot recursively enter post. The
