+        }catch(const std::exception&){return false;}};
+        std::cout<<"{\"accepted\":"<<(accepts(true)?"true":"false")<<",\"legacy\":"<<(accepts(false)?"true":"false")<<"}\n";
+    }
+    return std::cin.bad()?2:0;
+}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}

